from statistics import mean
from paths50 import *
def number(x):return f"{x:.2f}".replace(".",",")
def main():
    rr=get(D50/"results.json");groups=rr["groups"];all_=groups["all"];primary=all_["contrasts"]["true-lex"]
    n=all_["n"];matched=get(D50/"matching.json");t=get(D50/"answer-seal.json");ins=get(D50/"input-seal.json")
    def effect(g="all",pair="true-lex",j=1,key="cluster_ci"):
        s=groups[g]["contrasts"][pair];a,b=s[key][j]
        return f'{number(s["pp"][j])} [{number(a)}; {number(b)}]'
    c=get(D50/"contexts.json.gz");lengths=[r["refs"]["true"][2] for r in c.values()]
    ans=get(D50/"answers.json.gz");tot=sum(v["tokens"] for v in ans.values())
    cf=all_["means"];sh=[v for k,v in rr["mean_doc_recall"].items() if k.startswith("sham")]
    txt=["# Реальные переходы по упоминанию и ответы Qwen на 2WikiMultiHopQA","",
        f'В заранее выбранной панели из {n} вопросов переход к заголовку, упомянутому в первом абзаце, дал **{number(cf["true"][1]*100)} Answer F1** против **{number(cf["lex"][1]*100)}** у расширенного лексического поиска. Первичная парная разность **{effect()} п.п.** Среднее пяти контролей с подменой адреса составило {number(cf["sham"][1]*100)} F1, разность подлинного перехода с ними — **{effect("all","true-sham")} п.п.** Интервалы рассчитаны по 10 000 перевыборок {rr["clusters"]} точных первых документов. [Протокол](./PROTOCOL_RU.md) · [Полные результаты](./results.json)',"",
        "| Выбор второго документа | EM, % | Answer F1 | Все заголовки опор найдены, % | Средняя доля найденных опор, % | Строка ответа в тексте, % |",
        "|---|---:|---:|---:|---:|---:|"]
    for key,name,recall in [("true","Подлинное упоминание",rr["mean_doc_recall"]["true"]),("lex","Лексическое расширение",rr["mean_doc_recall"]["lex"]),("sham","Переназначение, среднее пяти семян",mean(sh))]:
        em,f1,full,present=cf[key];txt.append("| "+name+" | "+" | ".join(number(v*100) for v in [em,f1,full,recall,present])+" |")
    txt+=["",f'Разность EM к лексическому контролю — {effect(j=0)} п.п. На {primary["wins"][1]} вопросах F1 вырос, на {primary["losses"][1]} упал и на {n-primary["wins"][1]-primary["losses"][1]} остался прежним. Разность placebo с лексическим контролем — {effect("all","sham-lex")} п.п.; при повторной выборке также семян true минус placebo — {effect("all","true-sham",key="cluster_seed_ci")} п.п. При выборе двух документов полнота опор означает наличие всех размеченных заголовков. Это оценка доступного материала, а не проверка правильности рассуждения самой модели.',"",
        "| Срез | Вопросов | F1, подлинный переход | F1, лексический | Разность, п.п. [95%] |","|---|---:|---:|---:|---:|"]
    for k,g in groups.items():
        if k=="all":continue
        name={"same":"Второй ID совпадает","switched":"Второй ID изменился"}.get(k,k.removeprefix("type_"))
        txt.append(f'| {name} | {g["n"]} | {number(g["means"]["true"][1]*100)} | {number(g["means"]["lex"][1]*100)} | {effect(k)} |')
    txt+=["",f'У {groups["switched"]["n"]}/{n} вопросов (46,88%) данные действительно перенаправляют второе чтение. Для остальных {groups["same"]["n"]} вход true и lex одинаков. На переключениях подлинный адрес против подмены даёт {effect("switched","true-sham")} п.п. F1. Срезы по типам задач описательные. В каждом из 2 250 переключившихся placebo-назначений второй документ удалось заменить на неупомянутый, сохранив число и позиции рёбер и решение сменить лексического лидера. Медианное абсолютное расхождение по расширенному рангу равно {matched["all"]["median"][0]:g}, по длине заголовка — {matched["all"]["median"][3]:g} слову. Длина самого заголовка совпала точно в {matched["identical_title_length_redirected"]}/2 250 случаях. Полная длина доставленного контекста совпала во всех семи ветвях каждого вопроса. [Проверка сопоставления](./matching.json) · [Порядки](./orders.json.gz)',"",
        "### Панель, официальная метрика и воспроизводимость","",
        f'Оценены 960 из 12 576 dev-записей, выбранные по хешу исходного ID. Авторский parquet и официальный архив с Wikidata-идентификаторами дали идентичные вопросы, названия и предложения всех 960 примеров. Для {rr["alias_extended_questions"]} вопросов в золотой набор действительно добавились алиасы или демонимы. Официальная процедура v1.1 воспроизвела опубликованные агрегаты каждой из семи ветвей. Независимая реализация подтвердила баллы каждого ответа. [Официальный оценщик](https://github.com/Alab-NII/2wikimultihop/blob/13800e5be57df1b4040b9b1588c6c811779e69e9/2wikimultihop_evaluate_v1.1.py) · [Ответы и контрольные суммы](./answer-seal.json)',"",
        'Все 960 вопросов ранее участвовали в R32 при оценке retrieval. Первые адреса и четыре базовых вторых адреса совпали с той процедурой в каждом случае. Для Qwen это другой корпус относительно R46–49 MuSiQue. С предыдущими 1 024 train и 2 417 dev вопросами MuSiQue нет совпадений полных нормализованных вопросов или ID. Точный заголовок вместе с текстом встречался в трёх каталогах против панели train и в восьми против панели dev. Надёжных данных о составе предобучения Qwen для этих вопросов нет. [Состав панели и перекрытия](./panel.json)',"",
        f'Работал локальный Qwen3-4B-Instruct-2507 Q4_K_M на RTX 3090. Фактический вход — в среднем {number(rr["input_mean"])} токена, от {min(lengths)} до {max(lengths)}. {ins["logical"]} логических ответов потребовали {ins["unique"]} новых уникальных вызовов и 32 контрольных повтора. При максимуме 96 выходных токенов модель сгенерировала {tot} токенов на уникальных запросах. Продолжительность генерации с повторами — {number(t["seconds"])} с. Расхождений на повторах — {t["different"]}. Опыт относится к этой модели и выбору двух документов в предоставленном каталоге. [Воспроизведение](./REPRODUCE_RU.md) · [Исходы каждого вопроса](./outcomes.json.gz)']
    txt += ["", "После записи всех ответов и повторов клиент R49 при оформлении квитанции обратился к отсутствовавшей локальной копии runtime.py. До открытия эталонов мы сверили все 2 578 ответов со строками исходного журнала, порядок обращений, 32 повтора и 2 610 записей сервера. Время выше отсчитывается от первого назначения задачи серверу до завершения последнего повтора. Поставка содержит побайтную копию клиента R49 для повторного запуска. [Восстановление квитанции](./seal50.py) · [Замеры сервера](./costs.json)"]
    (D50/"REPORT_RU.md").write_bytes(("\n".join(txt)+"\n").encode())
if __name__=="__main__":main()
